def parse_list(el, depth=0):
    flows = []
    ordered = el.tag.lower() == "ol"
    for idx, li in enumerate(el.findall("li"), start=1):
        marker = f"{idx}." if ordered else ("—" if depth == 0 else "·")
        sub = [c for c in li if c.tag.lower() in ("ul", "ol")]
        parts = [esc(li.text)] if li.text else []
        for c in li:
            if c.tag.lower() in ("ul", "ol"):
                continue
            parts.append(inline(c))
        style = S["li"] if depth == 0 else S["li2"]
        flows.append(Paragraph("".join(parts) or "&nbsp;", style, bulletText=marker))
        for s in sub:
            flows.extend(parse_list(s, depth + 1))
    return flows
